// Log-replay harness self-consistency: a log generated by the model itself replays with small residuals.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { replay, parseCsv } from '../../tools/replay.mjs';
import { Simulation } from '../../src/sim/index.js';
import { setupCruise, setMap } from '../../src/sim/pilot.js';
import { KT } from '../../src/sim/airframe.js';

test('replay: a synthetic EDM log produced by the model replays with EGT/CHT/OIL RMS < 25°F', () => {
  const sim = new Simulation({ seed: 5 });
  setupCruise(sim, { alt: 6000, rpm: 2400, map: 22, rBar: 1.08 });
  const rows = [];
  const record = (t) =>
    rows.push({
      TIME: t, ALT: sim.flight.alt, IAS: (sim.flight.tas / KT) * Math.sqrt(sim.atm.sigma), OAT: sim.atm.t,
      RPM: sim.engine.rpm, MAP: sim.engine.map, FF: sim.engine.gph, OIL: sim.engine.oil,
      E1: sim.engine.egtProbe[0], E2: sim.engine.egtProbe[1], E3: sim.engine.egtProbe[2], E4: sim.engine.egtProbe[3],
      C1: sim.engine.cht[0], C2: sim.engine.cht[1], C3: sim.engine.cht[2], C4: sim.engine.cht[3],
    });
  let t = 0;
  for (let k = 0; k < 40; k++) {
    record(t);
    sim.run(6);
    t += 6;
  }
  setMap(sim, 19, 10); // a power change mid-log
  for (let k = 0; k < 40; k++) {
    record(t + k * 6);
    sim.run(6);
  }
  const rep = replay(rows, { seed: 5 });
  assert.ok(rep.egt.rms < 25, `EGT rms ${rep.egt.rms.toFixed(1)}`);
  assert.ok(rep.cht.rms < 25, `CHT rms ${rep.cht.rms.toFixed(1)}`);
  assert.ok(rep.oil.rms < 25, `OIL rms ${rep.oil.rms.toFixed(1)}`);
});

test('replay: CSV parser reads EzTrends-style headers case-insensitively', () => {
  const rows = parseCsv('e1,E2,c1,RPM,map,FF\n1350,1360,380,2400,22.0,9.6\n');
  assert.deepEqual(rows[0], { E1: 1350, E2: 1360, C1: 380, RPM: 2400, MAP: 22, FF: 9.6 });
});
